/// <summary>
/// extension of FDS SalesTable
/// </summary>
[ExtensionOf(formDataSourceStr(SalesTable, SalesTable))]
final class AVASalesTableFds_SalesTable_Extension
{
}

Method.Source:
/// <summary>
/// AVA
/// </summary>
public void init()
{
    next init();

    this.object(fieldNum(SalesTable, KCS_ChainLineDiscCode)).allowEdit(false);
}

/// <summary>
/// Extension of method active
/// </summary>
/// <returns>int</returns>
public int active()
{
    int ret = next active();
    SalesTable avaSalesTable = this.cursor();

    if(avaSalesTable.SalesType == SalesType::Journal
        && avaSalesTable.AVADelegatedToAgent == NoYes::No)
    {
        element.avaEnableDelegationButtons(NoYes::Yes);
    }
    else if(avaSalesTable.SalesType == SalesType::Journal
        && avaSalesTable.AVADelegatedToAgent == NoYes::Yes)
    {
        element.avaEnableDelegationButtons(NoYes::No);
    }
    else if (avaSalesTable.isInterCompanyOrder())
    {
        if (avaSalesTable.AVADelegatedToAgentIC)
        {
            element.avaEnableDelegationButtons(NoYes::No);
        }
        else
        {
            element.avaEnableDelegationButtons(NoYes::Yes);
        }
    }
    else
    {
        element.avaDisableDelegationButtons();
    }

    return ret;
}
